## Fix Summary

**Problem:** When an option has multiple names/aliases (e.g., `-b, --base-url`) and a default value, the default was incorrectly applied to all alias names even when one alias was already parsed.

**Root cause:** In the `mri` method of `CAC.ts`:
1. First, defaults are set for ALL alias names of each option
2. Then, parsed values are set using only the specific name that was parsed (e.g., `--base-url` becomes `baseUrl` after camelCasing)
3. The short alias `b` still retained the default value because it was never updated

**Fix:** Added code in `src/CAC.ts` that, after setting a parsed option value, also sets all other alias names of that option to the same value:

```typescript
// Also set all alias names of this option to the same value
const option = cliOptions.find(o => o.names.includes(keys[0]))
if (option) {
  for (const name of option.names) {
    if (name !== keys[0]) {
      options[name] = parsed[key]
    }
  }
}
```

This ensures that all aliases are synchronized when an option is explicitly provided by the user. All existing tests pass, and the fix correctly handles both long form (`--base-url`) and short form (`-b`) parsing.

import { removeBrackets, camelcaseOptionName } from './utils'

interface OptionConfig {
  default?: any
  type?: any[]
}

export default class Option {
  /** Option name */
  name: string
  /** Option name and aliases */
  names: string[]
  isBoolean?: boolean
  // `required` will be a boolean for options with brackets
  required?: boolean
  config: OptionConfig
  negated: boolean

  constructor(
    public rawName: string,
    public description: string,
    config?: OptionConfig
  ) {
    this.config = Object.assign({}, config)

    // You may use cli.option('--env.* [value]', 'desc') to denote a dot-nested option
    rawName = rawName.replace(/\.\*/g, '')

    this.negated = false
    this.names = removeBrackets(rawName)
      .split(',')
      .map((v: string) => {
        let name = v.trim().replace(/^-{1,2}/, '')
        if (name.startsWith('no-')) {
          this.negated = true
          name = name.replace(/^no-/, '')
        }

        return camelcaseOptionName(name)
      })
      .sort((a, b) => (a.length > b.length ? 1 : -1)) // Sort names

    // Use the longest name (last one) as actual option name
    this.name = this.names[this.names.length - 1]

    if (this.negated && this.config.default == null) {
      this.config.default = true
    }

    if (rawName.includes('<')) {
      this.required = true
    } else if (rawName.includes('[')) {
      this.required = false
    } else {
      // No arg needed, it's boolean flag
      this.isBoolean = true
    }
  }
}

